INSERT INTO `energy_conservation_reports` (`id`, `report_month`, `campus`, `previous_month_bill`, `current_month_bill`, `previous_month_consumption`, `current_month_consumption`, `remarks_analysis`, `measures_implemented`, `other_measures`, `summary_of_accomplishments`, `status`, `reviewed_by_name`, `submitted_at`, `created_by`, `created_at`, `updated_at`) VALUES
(9, '2026-03', 'CvSU Carmona Campus', NULL, 227760.97, NULL, 15360.00, 'Based on the MERALCO billing period of 22 January 2026 to 21 February 2026, the campus recorded an electricity consumption of 15,360 kWh with a total electricity bill of ₱227,760.97.', '[\"lights_off\",\"ac_management\",\"natural_lighting\",\"shutdown_after_hours\",\"unplug_unused\",\"preventive_maintenance\",\"info_campaign\"]', NULL, NULL, 'submitted', 'Jenny Beb F. Espineli, Ph.D.', '2026-07-21 01:35:21', 15, '2026-07-21 01:17:41', '2026-07-21 01:35:21'),
(10, '2026-04', 'CvSU Carmona Campus', 227760.97, 225468.43, 15360.00, 13280.00, 'Based on the MERALCO billing period of 22 March 2026 to 21 April 2026,\r\nthe campus recorded an electricity consumption of 13,280 kWh with a total electricity bill of\r\nP225,468.43. Compared with the previous billing period, electricity consumption decreased\r\nby 2,080 kWh (13.54%), while the total eiectricity bill decreased by P2,292.54 (1.01%). The\r\nreduction indicates that the campus\' energy conservation initiatives including lighting\r\nmanagement, air-conditioning control, and responsible operation of electrical equipment\r\ncontributed to improved energy efficiency despite fluctuations in electricity rates.', '[\"lights_off\",\"ac_management\",\"natural_lighting\",\"shutdown_after_hours\",\"unplug_unused\",\"preventive_maintenance\",\"info_campaign\"]', NULL, NULL, 'submitted', 'Jenny Beb F. Espineli, Ph.D.', '2026-07-21 19:44:48', 15, '2026-07-21 01:33:16', '2026-07-21 19:44:48'),
(13, '2026-05', 'CvSU Carmona Campus', 225468.43, 227741.42, 13280.00, 11360.00, 'Based on the MERALCO billing period of 22 April 2026 to 21 May 2026, the campus recorded an electricity consumption of 11,360 kWh with a total electricity bill of ₱227,741.42. Compared with the previous billing period, electricity consumption decreased by 1,920 kWh (14.46%). Despite the reduction in energy consumption, the total electricity bill increased by ₱2,272.99 (1.01%) due to higher generation and transmission charges.', '[\"lights_off\",\"ac_management\",\"natural_lighting\",\"shutdown_after_hours\",\"unplug_unused\",\"preventive_maintenance\",\"info_campaign\"]', NULL, NULL, 'submitted', 'Jenny Beb F. Espineli, Ph.D.', '2026-07-21 19:44:56', 15, '2026-07-21 01:50:02', '2026-07-21 19:44:56'),
(15, '2026-06', 'CvSU Carmona Campus', 227741.42, NULL, 11360.00, NULL, NULL, '[\"lights_off\",\"ac_management\",\"natural_lighting\",\"shutdown_after_hours\",\"unplug_unused\",\"preventive_maintenance\",\"info_campaign\"]', NULL, NULL, 'submitted', 'Jenny Beb F. Espineli, Ph.D.', '2026-07-27 16:57:47', 15, '2026-07-21 19:47:43', '2026-07-27 16:59:11'),
(18, '2026-07', 'CvSU Carmona Campus', 227741.42, 188669.32, 11360.00, 10880.00, 'Based on the MERALCO billing period of 22 June 2026 to 21 July 2026, the campus recorded an electricity consumption of 10,880 kWh with a total electricity bill of ₱188,669.32. Compared with the previous billing period, electricity consumption decreased by 480 kWh (4.23%). In line with the reduction in energy consumption, the total electricity bill also decreased by ₱39,072.10 (17.16%), reflecting lower generation and transmission charges alongside reduced consumption.', '[\"lights_off\",\"ac_management\",\"natural_lighting\",\"shutdown_after_hours\",\"unplug_unused\",\"preventive_maintenance\",\"info_campaign\"]', NULL, 'During the July 2026 reporting period, the campus sustained its energy conservation initiatives through continuous monitoring of electricity consumption, implementation of the Lights-Off Policy, responsible air-conditioning management, and preventive maintenance of electrical facilities. These initiatives resulted in a reduction of 480 kWh (4.23%) in electricity consumption compared with the previous billing period.', 'submitted', 'Jenny Beb F. Espineli, Ph.D.', '2026-07-27 17:03:35', 15, '2026-07-27 16:08:34', '2026-07-27 17:03:35');
